16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Email;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.time.LocalDate;
26	import java.util.*;
27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "postcode")
48	    private String postcode;
49	
50	    @Column(name = "telephone")
51	    @NotEmpty
52	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
53	    private String telephone;
54	
55	    @Column(name = "email")
56	    @Email
57	    private String email;
58	
59	    @Column(name = "registration_date")
60	    private LocalDate registrationDate;
61	
62	    @Column(name = "customer_code")
63	    private String customerCode;
64	
65	    @Column(name = "household_id")
66	    private String householdId;
67	
68	    @Column(name = "namesake_count")
69	    private Integer namesakeCount;
70	
71	    @Column(name = "bulk_signup_warning")
72	    private Boolean bulkSignupWarning;
73	
74	    @Column(name = "household_size")
75	    private Integer householdSize;
76	
77	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
78	    private Set<Pet> pets;
79	
80	    public String getAddress() {
81	        return this.address;
82	    }
83	
84	    public void setAddress(String address) {
85	        this.address = address;
86	    }
87	
88	    public String getCity() {
89	        return this.city;
90	    }
91	
92	    public void setCity(String city) {
93	        this.city = city;
94	    }
95	
96	    public String getPostcode() {
97	        return this.postcode;
98	    }
99	
100	    public void setPostcode(String postcode) {
101	        this.postcode = postcode;
102	    }
103	
104	    public String getTelephone() {
105	        return this.telephone;
106	    }
107	
108	    public void setTelephone(String telephone) {
109	        this.telephone = telephone;
110	    }
111	
112	    public String getEmail() {
113	        return this.email;
114	    }
115	
116	    public void setEmail(String email) {
117	        this.email = email == null ? null : email.toLowerCase();
118	    }
119	
120	    public LocalDate getRegistrationDate() {
121	        return this.registrationDate;
122	    }
123	
124	    public void setRegistrationDate(LocalDate registrationDate) {
125	        this.registrationDate = registrationDate;
126	    }
127	
128	    public String getCustomerCode() {
129	        return this.customerCode;
130	    }
131	
132	    public void setCustomerCode(String customerCode) {
133	        this.customerCode = customerCode;
134	    }
135	
136	    public String getHouseholdId() {
137	        return this.householdId;
138	    }
139	
140	    public void setHouseholdId(String householdId) {
141	        this.householdId = householdId;
142	    }
143	
144	    public Integer getNamesakeCount() {
145	        return this.namesakeCount;
146	    }
147	
148	    public void setNamesakeCount(Integer namesakeCount) {
149	        this.namesakeCount = namesakeCount;
150	    }
151	
152	    public Boolean getBulkSignupWarning() {
153	        return this.bulkSignupWarning;
154	    }
155	
156	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
157	        this.bulkSignupWarning = bulkSignupWarning;
158	    }
159	
160	    public Integer getHouseholdSize() {
161	        return this.householdSize;
162	    }
163	
164	    public void setHouseholdSize(Integer householdSize) {
165	        this.householdSize = householdSize;
166	    }
167	
168	    /**
169	     * The owner's name formatted as {@code 'LastName, FirstName'} from the stored names.
170	     */
171	    public String getDisplayName() {
172	        return this.getLastName() + ", " + this.getFirstName();
173	    }
174	
175	    /**
176	     * The owner's initials: the upper-cased first letters of firstName and lastName,
177	     * dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
178	     */
179	    public String getInitials() {
180	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
181	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
182	    }
183	
184	    /**
185	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY is the
186	     * last two digits of the registrationDate year, e.g. {@code 'LON-SMI-0007-M26'}.
187	     */
188	    public String getMembershipNumber() {
189	        return this.customerCode + "-M" + String.format("%02d", this.registrationDate.getYear() % 100);
190	    }
191	
192	    /**
193	     * The Luhn check digit (a single digit, {@code 0}-{@code 9}) computed over the decimal digits
194	     * contained in the owner's {@link #customerCode}.
195	     */
196	    public int getCheckDigit() {
197	        return luhnCheckDigit(this.customerCode);
198	    }
199	
200	    /**
201	     * The Luhn check digit (a single digit, {@code 0}-{@code 9}) over the decimal digits
202	     * contained in {@code value}. Reading the digits right to left, every second one is
203	     * doubled (subtracting 9 whenever doubling yields a value above 9); the transformed
204	     * digits are summed, and the check digit is the amount that must be added to that sum to
205	     * reach the next multiple of ten. Any non-digit character in {@code value} is ignored, so
206	     * the digit is taken over exactly the digits the string carries.
207	     */
208	    private static int luhnCheckDigit(String value) {
209	        int sum = 0;
210	        boolean doubling = true;
211	        for (int i = value.length() - 1; i >= 0; i--) {
212	            char c = value.charAt(i);
213	            if (c < '0' || c > '9') {
214	                continue;
215	            }
216	            int digit = c - '0';
217	            if (doubling) {
218	                digit *= 2;
219	                if (digit > 9) {
220	                    digit -= 9;
221	                }
222	            }
223	            sum += digit;
224	            doubling = !doubling;
225	        }
226	        return (10 - (sum % 10)) % 10;
227	    }
228	
229	    /** Fixed city-to-region table used to derive an owner's locality. */
230	    private static final Map<String, String> CITY_REGION = Map.of(
231	        "Sydney", "NSW",
232	        "Melbourne", "VIC",
233	        "Brisbane", "QLD");
234	
235	    /** The region reported for a city that is not present in {@link #CITY_REGION}. */
236	    public static final String UNKNOWN_REGION = "UNKNOWN";
237	
238	    /**
239	     * The canonical region for a city, derived from the fixed city-to-region table
240	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}), or
241	     * {@link #UNKNOWN_REGION} when the city is not in the table. This is the single
242	     * source of the city-to-region mapping, shared by every rule that is keyed by
243	     * region so the mapping is never re-derived elsewhere.
244	     */
245	    public static String regionOf(String city) {
246	        return CITY_REGION.getOrDefault(city, UNKNOWN_REGION);
247	    }
248	
249	    /**
250	     * The owner's locality. The postcode is preferred: when it falls within a known
251	     * {@linkplain #REGION_POSTCODE_RANGE region postcode range} that region is returned,
252	     * which disambiguates cities that share a name. Only when the postcode is absent or in
253	     * no known range does this fall back to the {@linkplain #regionOf(String) city-to-region
254	     * table}, yielding {@link #UNKNOWN_REGION} when the city has no known region.
255	     */
256	    public String getLocality() {
257	        String byPostcode = getRegion();
258	        return byPostcode != null ? byPostcode : regionOf(this.city);
259	    }
260	
261	    /**
262	     * The region derived from this owner's postcode alone: the region whose fixed
263	     * {@linkplain #REGION_POSTCODE_RANGE postcode range} contains the postcode, or {@code null}
264	     * when the postcode is absent, not four digits, or in no known range. This is the postcode
265	     * half of {@link #getLocality()} and the single place a region is read from an owner's
266	     * postcode, so every rule keyed by the postcode-derived region shares one derivation.
267	     */
268	    public String getRegion() {
269	        return regionOfPostcode(this.postcode);
270	    }
271	
272	    /**
273	     * The region whose fixed {@linkplain #REGION_POSTCODE_RANGE postcode range} contains the
274	     * given postcode, or {@code null} when the postcode is {@code null}, not four digits, or in
275	     * no known range.
276	     */
277	    private static String regionOfPostcode(String postcode) {
278	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
279	            return null;
280	        }
281	        int value = Integer.parseInt(postcode);
282	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGE.entrySet()) {
283	            int[] range = entry.getValue();
284	            if (value >= range[0] && value <= range[1]) {
285	                return entry.getKey();
286	            }
287	        }
288	        return null;
289	    }
290	
291	    /**
292	     * Fixed inclusive 4-digit postcode ranges keyed by region, as {@code {low, high}}:
293	     * {@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}. A region not
294	     * listed here (i.e. {@link #UNKNOWN_REGION}) accepts any 4-digit postcode.
295	     */
296	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
297	        "NSW", new int[] {2000, 2099},
298	        "VIC", new int[] {3000, 3099},
299	        "QLD", new int[] {4000, 4099});
300	
301	    /**
302	     * Whether this owner's postcode is acceptable for its city. Postcode is optional, so a
303	     * {@code null} postcode is accepted. When present it must be four digits and, for a city
304	     * whose {@linkplain #regionOf(String) region} is known, fall within that region's fixed
305	     * inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}); a
306	     * city with no known region accepts any 4-digit postcode.
307	     */
308	    public boolean isPostcodeValid() {
309	        if (this.postcode == null) {
310	            return true;
311	        }
312	        if (!this.postcode.matches("[0-9]{4}")) {
313	            return false;
314	        }
315	        int[] range = REGION_POSTCODE_RANGE.get(regionOf(this.city));
316	        if (range == null) {
317	            return true;
318	        }
319	        int value = Integer.parseInt(this.postcode);
320	        return value >= range[0] && value <= range[1];
321	    }
322	
323	    /**
324	     * The owner's membership level, a number from 1 to 3 determined on creation: it starts at 1,
325	     * gains 1 when an email is present, gains 1 when namesakeCount is 0, and is capped at 3.
326	     * Level 4 is reserved for tenure.
327	     */
328	    public Integer getMembershipLevel() {
329	        int level = 1;
330	        if (this.email != null && !this.email.isEmpty()) {
331	            level++;
332	        }
333	        if (this.namesakeCount != null && this.namesakeCount == 0) {
334	            level++;
335	        }
336	        return Math.min(level, 3);
337	    }
338	
339	    /**
340	     * The owner's preferred contact channel: {@code 'EMAIL'} when an email is present,
341	     * otherwise {@code 'PHONE'}.
342	     */
343	    public String getContactPreference() {
344	        return (this.email != null && !this.email.isEmpty()) ? "EMAIL" : "PHONE";
345	    }
346	
347	    /**
348	     * The owner's identity key: the single derived value used for duplicate detection.
349	     * It joins the normalized (E.164) telephone, the email (already lower-cased, or the
350	     * empty string when absent) and the householdId (or the empty string when the owner
351	     * has no household) with {@code '|'}, e.g. {@code '+61412345678|jane@example.test|3C1A9F2B7D4E'}.
352	     * Two owners are duplicates only when their whole identity keys are equal.
353	     */
354	    public String getIdentityKey() {
355	        String telephonePart = this.telephone == null ? "" : this.telephone;
356	        String emailPart = this.email == null ? "" : this.email;
357	        String householdPart = this.householdId == null ? "" : this.householdId;
358	        return telephonePart + "|" + emailPart + "|" + householdPart;
359	    }
360	
361	    protected Set<Pet> getPetsInternal() {
362	        if (this.pets == null) {
363	            this.pets = new HashSet<>();
364	        }
365	        return this.pets;
366	    }
367	
368	    protected void setPetsInternal(Set<Pet> pets) {
369	        this.pets = pets;
370	    }
371	
372	    public List<Pet> getPets() {
373	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
374	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
375	        return Collections.unmodifiableList(sortedPets);
376	    }
377	
378	    public void setPets(List<Pet> pets) {
379	        this.pets = new HashSet<>(pets);
380	    }
381	
382	    public void addPet(Pet pet) {
383	        getPetsInternal().add(pet);
384	        pet.setOwner(this);
385	    }
386	
387	    /**
388	     * Return the Pet with the given name, or null if none found for this Owner.
389	     *
390	     * @param name to test
391	     * @return true if pet name is already in use
392	     */
393	    public Pet getPet(String name) {
394	        return getPet(name, false);
395	    }
396	
397	    /**
398	     * Return the Pet with the given name, or null if none found for this Owner.
399	     *
400	     * @param name to test
401	     * @return true if pet name is already in use
402	     */
403	    public Pet getPet(String name, boolean ignoreNew) {
404	        name = name.toLowerCase();
405	        for (Pet pet : getPetsInternal()) {
406	            if (!ignoreNew || !pet.isNew()) {
407	                String compName = pet.getName();
408	                compName = compName.toLowerCase();
409	                if (compName.equals(name)) {
410	                    return pet;
411	                }
412	            }
413	        }
414	        return null;
415	    }
416	
417	    public Pet getPet(Integer petId) {
418	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
419	    }
420	
421	    @Override
422	    public String toString() {
423	        return new ToStringCreator(this)
424	
425	            .append("id", this.getId())
426	            .append("new", this.isNew())
427	            .append("lastName", this.getLastName())
428	            .append("firstName", this.getFirstName())
429	            .append("address", this.address)
430	            .append("city", this.city)
431	            .append("telephone", this.telephone)
432	            .append("email", this.email)
433	            .toString();
434	    }
435	}
